"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"bus-dad","metadata":{"permalink":"/blog/bus-dad","source":"@site/blog/2025-12-19-bus-dad.md","title":"\u516c\u8eca\u4e0a\u7684\u7236\u89aa","description":"\u8a00\u6559\u4e0d\u5982\u8eab\u6559","date":"2025-12-19T00:00:00.000Z","tags":[],"readingTime":2.09,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"bus-dad","title":"\u516c\u8eca\u4e0a\u7684\u7236\u89aa","authors":["tzuchun"],"description":"\u8a00\u6559\u4e0d\u5982\u8eab\u6559","rss":true},"unlisted":false,"nextItem":{"title":"\u7a7f\u8d8a\u6642\u7a7a\u7684\u65b9\u6cd5","permalink":"/blog/music-time-travel"}},"content":"\u6628\u5929\u5728\u642d\u516c\u8eca\u7684\u6642\u5019\uff0c\u767c\u751f\u4e86\u9019\u6a23\u7684\u72c0\u6cc1\u3002\\n\\n\u8eca\u4e0a\u539f\u672c\u4e00\u7247\u5bc2\u975c\uff0c\u4eba\u5011\u5404\u81ea\u7576\u8457\u4f4e\u982d\u65cf\uff0c\u7a7a\u6c23\u4e2d\u5269\u4e0b\u5f15\u64ce\u7684\u4f4e\u983b\u904b\u8f49\u8072\u3002\\n\\n\u5ffd\u7136\uff0c**\u4e00\u9663\u6025\u4fc3\u3001\u5e7e\u4e4e\u5f35\u72c2\u7684\u543c\u53eb\u6253\u7834\u4e86\u5bc2\u975c**\uff0c\u8b93\u6240\u6709\u4eba\u7684\u8eab\u9ad4\u53cd\u5c04\u6027\u5730\u986b\u6296\u4e86\u4e00\u4e0b\uff0c\u7d1b\u7d1b\u628a\u982d\u62ac\u8d77\u4f86\uff0c\u6ce8\u8996\u8457\u8072\u97f3\u7684\u4f86\u6e90\uff0c\u8a66\u5716\u7406\u89e3\u767c\u751f\u4e86\u4ec0\u9ebc\u3002\\n\\n\u300c**\u4e0b\u8eca\uff01\uff01\uff01**\u300d\\n\\n\u4e00\u4f4d\u76ee\u6e2c\u7d04 45 \u6b72\u7684\u4e2d\u5e74\u7537\u5b50\u7528\u611f\u89ba\u8981\u6253\u67b6\u7684\u65b9\u5f0f\u5636\u543c\u8457\u3002\\n\\n\u6211\u5f88\u5feb\u5c31\u638c\u63e1\u72c0\u6cc1\uff0c\u61c9\u8a72\u662f\u57fa\u65bc\u67d0\u4e9b\u539f\u56e0\uff0c\u516c\u8eca\u5230\u9019\u4f4d\u5148\u751f\u60f3\u8981\u4e0b\u8eca\u7684\u7ad9\u6642\uff0c\u4e26\u6c92\u6709\u505c\u4e0b\u4f86\uff0c\u65bc\u662f\u4ed6\u7528\u9019\u6a23\u7684\u65b9\u5f0f\u8b93\u53f8\u6a5f\u505c\u4e0b\uff0c\u6253\u958b\u8eca\u9580\u7d66\u4ed6\u4e0b\u8eca\u3002\\n\\n\u8eca\u9580\u958b\u5f8c\uff0c\u4ed6\u6c23\u6c96\u6c96\u5730\u8df3\u4e0b\u8eca\uff0c**\u65c1\u908a\u8ddf\u8457\u4e00\u4f4d\u76ee\u6e2c 10 \u6b72\u7684\u5c0f\u7537\u5b69\uff0c\u6211\u60f3\u662f\u4ed6\u7684\u5152\u5b50**\u3002\u800c\u4ed6\u5011\u8df3\u4e0b\u8eca\u7684\u540c\u6642\uff0c\u53f8\u6a5f\u5247\u788e\u5ff5\u8457\uff1a\u300c\u8981\u4e0b\u8eca\u4e0d\u6309\u4e0b\u8eca\u9234\uff0c\u9084\u5728\u5927\u8072\u4ec0\u9ebc...\u300d\\n\\n**\u6211\u4e0d\u60f3\u8a08\u8f03\u9019\u4f4d\u5148\u751f\u6709\u6c92\u6709\u6309\u4e0b\u8eca\u9234\uff0c\u4e5f\u4e0d\u89ba\u5f97\u7528\u53e3\u982d\u544a\u77e5\u53f8\u6a5f\u300c\u6211\u8981\u4e0b\u8eca\u300d\u6709\u4ec0\u9ebc\u554f\u984c**\u3002\u56de\u60f3\u8d77\u4f86\uff0c\u6211\u5176\u5be6\u6709\u807d\u898b\u9019\u4f4d\u5148\u751f\u4e00\u958b\u59cb\u7528\u6b63\u5e38\u97f3\u91cf\u8b1b\u4e86\u4e00\u6b21\u300c\u4e0b\u8eca\u300d\uff0c\u53ef\u662f\u516c\u8eca\u4e0a\u7684\u566a\u97f3\u6bd4\u8f03\u5927\uff0c\u53f8\u6a5f\u4e26\u6c92\u6709\u807d\u898b\uff0c\u4e5f\u5c31\u6c92\u6709\u9760\u7ad9\u3002\u6b63\u56e0\u70ba\u9019\u6a23\uff0c\u63a5\u8457\u9019\u4f4d\u5148\u751f\u624d\u6703\u70ba\u4e86\u300c\u6211\u8981\u4e0b\u8eca\u300d\u9019\u7a2e\u4e8b\uff0c\u6c23\u5f97\u6e3e\u8eab\u7dca\u7e43\uff0c\u9084\u6025\u5f97\u9762\u7d05\u8033\u8d64\uff0c\u50cf\u662f\u9ad8\u8840\u58d3\u8981\u767c\u4f5c\u4e86\u3002\\n\\n\u7576\u7136\uff0c\u9019\u4f4d\u5148\u751f\u9762\u5c0d\u4e8b\u60c5\u7684\u53cd\u61c9\u65b9\u5f0f\u7528\u4e0d\u8457\u6211\u4f86\u7ba1\uff0c\u4f46\u771f\u6b63\u8b93\u6211\u5728\u610f\u7684\uff0c\u662f\u6211\u8a8d\u70ba**\u4ed6\u5728\u4ed6\u5152\u5b50\u9762\u524d\u505a\u4e86\u6700\u5dee\u52c1\u7684\u793a\u7bc4**\u3002\u5fc3\u7406\u5b78\u7684\u9818\u57df\u7814\u7a76\u53cd\u8986\u767c\u73fe\uff0c\u5bb6\u9577\u81ea\u5df1\u672c\u8eab\u600e\u9ebc\u8655\u7406\u4e8b\u60c5\u7684\u300c\u8eab\u6559\u300d\uff0c\u6bd4\u8d77\u544a\u8a34\u5b69\u5b50\u61c9\u8a72\u600e\u9ebc\u505a\u7684\u300c\u8a00\u6559\u300d\uff0c\u5f71\u97ff\u529b\u8981\u5927\u5f97\u591a\uff0c\u5b69\u5b50\u9762\u5c0d\u4e8b\u60c5\u7684\u61c9\u5c0d\u65b9\u5f0f\uff0c\u4e5f\u7d93\u5e38\u6703\u4e0d\u81ea\u89ba\u5730\u6a21\u4eff\u81ea\u5df1\u7684\u7236\u6bcd\u3002\\n\\n\u9019\u4f4d\u5148\u751f\u9019\u6a23\u7684\u8655\u4e8b\u65b9\u5f0f\uff0c\u544a\u8a34\u4ed6\u5152\u5b50\u5169\u4ef6\u4e8b\u3002\\n\\n- \u5373\u4f7f\u662f\u300c\u4e0b\u8eca\u300d\u9019\u9ebc\u5c0f\u7684\u4e8b\uff0c\u4e5f\u8981\u7528\u9019\u9ebc\u6fc0\u52d5\u7684\u65b9\u5f0f\u61c9\u5c0d\\n- \u5982\u679c\u4e8b\u60c5\u4e0d\u5982\u9810\u671f\uff0c\u5c31\u7528\u5927\u543c\u5927\u53eb\u7684\u65b9\u5f0f\u8ddf\u5225\u4eba\u8aaa\u8a71\\n\\n\u5f80\u5f8c\u4ed6\u5152\u5b50**\u9047\u5230\u985e\u4f3c\u7684\u4e8b\u60c5\uff0c\u53ef\u80fd\u5c31\u6703\u7528\u4e00\u6a23\u7684\u65b9\u5f0f\u8655\u7406**\u3002\\n\\n\u4e0b\u8eca\u7d42\u7a76\u662f\u4e00\u4ef6\u518d\u5c0f\u4e0d\u904e\u7684\u4e8b\uff0c\u932f\u904e\u4e00\u7ad9\uff0c\u4e5f\u5c31\u662f\u5f9e\u4e0b\u4e00\u7ad9\u5f80\u56de\u8d70\u5e7e\u5341\u516c\u5c3a\u5c31\u597d\u4e86\u3002\u751f\u6d3b\u4e2d\uff0c\u9084\u6709\u4e00\u767e\u4ef6\u66f4\u8b93\u4eba\u5fc3\u7169\u3001\u982d\u75db\u7684\u4e8b\u60c5\u9700\u8981\u9762\u5c0d\uff0c**\u7576\u6211\u5011\u9023\u5c0f\u4e8b\u90fd\u7121\u6cd5\u6c88\u8457\u51b7\u975c\u7684\u8655\u7406\uff0c\u600e\u9ebc\u9762\u5c0d\u66f4\u591a\u5927\u4e8b\uff1f**\\n\\n\u4e5f\u8a31\u7576\u4e0b\uff0c\u9019\u4f4d\u5148\u751f\u89e3\u6c7a\u4e86\u4e00\u4ef6\u5c0f\u4e8b\uff1b\\n\\n\u4f46\u4ed6\u4e0d\u77e5\u9053\uff0c\u81ea\u5df1\u6b63\u5728\u5851\u9020\u5152\u5b50\u5c07\u4f86\u9762\u5c0d\u4e16\u754c\u7684\u65b9\u5f0f\u3002"},{"id":"music-time-travel","metadata":{"permalink":"/blog/music-time-travel","source":"@site/blog/2025-11-28-music-time-travel.md","title":"\u7a7f\u8d8a\u6642\u7a7a\u7684\u65b9\u6cd5","description":"\u6709\u6642\u5019\uff0c\u4e00\u9996\u6b4c\u5c31\u8db3\u4ee5\u8b93\u4eba\u7a7f\u8d8a\u6642\u7a7a","date":"2025-11-28T00:00:00.000Z","tags":[],"readingTime":2.58,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"music-time-travel","title":"\u7a7f\u8d8a\u6642\u7a7a\u7684\u65b9\u6cd5","authors":["tzuchun"],"date":"2025-11-28T00:00:00.000Z","description":"\u6709\u6642\u5019\uff0c\u4e00\u9996\u6b4c\u5c31\u8db3\u4ee5\u8b93\u4eba\u7a7f\u8d8a\u6642\u7a7a","image":"/img/IMG_0018.JPG"},"unlisted":false,"prevItem":{"title":"\u516c\u8eca\u4e0a\u7684\u7236\u89aa","permalink":"/blog/bus-dad"},"nextItem":{"title":"\u67b6\u500b\u4eba\u7db2\u7ad9\u7684\u4e09\u500b\u539f\u56e0","permalink":"/blog/benifits-of-website"}},"content":"\u5982\u679c\u60f3\u7a7f\u8d8a\u56de\u904e\u53bb\u7684\u67d0\u500b\u6642\u7a7a\uff0c\u53ef\u4ee5\u807d\u807d\u7576\u6642\u5e38\u807d\u7684\u6b4c\u3002\\n\\n\u6709\u6642\u5728\u9910\u5ef3\uff0c\u78b0\u5de7\u807d\u898b\u81ea\u5df1\u67d0\u500b\u6642\u671f\u5e38\u807d\u7684\u6b4c\uff0c\u8eab\u9ad4\u6703\u6709\u4e00\u7a2e\u5947\u7279\u7684\u611f\u89ba\uff0c\u5f77\u5f7f\u6211\u5df2\u7d93\u4e0d\u662f\u5728\u300c\u807d\u300d\u97f3\u6a02\uff0c\u800c\u662f\u8eab\u9ad4\u672c\u80fd\u5730\u300c\u8a8d\u5f97\u300d\u9019\u6bb5\u719f\u6089\u7684\u65cb\u5f8b\u3001\u6b4c\u8a5e\u3001\u7bc0\u594f\u3001\u8072\u97ff\u3002\u8a31\u591a\u8a18\u61b6\u3001\u611f\u53d7\u8207\u601d\u7dd2\u4e5f\u81ea\u7136\u5730\u6d6e\u73fe\u51fa\u4f86\uff0c\u6211\u7a31\u9019\u6a23\u7684\u72c0\u6cc1\u70ba\u300c\u97f3\u6a02\u8a18\u61b6\u300d\u3002\\n\\n\u5728\u6211\u7684\u6210\u9577\u904e\u7a0b\u4e2d\uff0c\u6211\u80fd\u60f3\u5230\u4e00\u4e9b\u6b4c\u66f2\u6709\u67d0\u500b\u6642\u7a7a\u7684\u4ee3\u8868\u6027\uff0c\u7e3d\u80fd\u559a\u8d77\u6211\u7684\u97f3\u6a02\u8a18\u61b6\u3002\\n\\n\u56de\u5230 2018 \u5e74\uff0c\u6211\u9084\u6b63\u5728\u8b80\u570b\u4e8c\uff0c\u90a3\u662f\u4e00\u500b TikTok\uff08\u6296\u97f3\uff09\u6975\u5ea6\u71b1\u9580\u7684\u6642\u4ee3\uff0c\u6642\u4e0b\u6700\u706b\u7d05\u7684\u6b4c\u66f2\uff0c\u4e5f\u5c31\u662f\u90a3\u4e9b\u6296\u97f3\u5f71\u7247\u4e2d\u7684\u80cc\u666f\u97f3\u6a02\uff0c\u6211\u81ea\u5df1\u6bd4\u8f03\u6709\u5370\u8c61\u7684\u6709\uff1a\u3008\u611b\u7684\u5c31\u662f\u4f60\u3009\u3001\u3008\u5e36\u4f60\u53bb\u65c5\u884c\u3009\u3001\u3008\u6211\u5011\u4e0d\u4e00\u6a23\u3009\u3001\u3008\u525b\u597d\u9047\u898b\u4f60\u3009\u3001\u3008\u8ffd\u5149\u8005\u3009\u7b49\u7b49\u3002\\n\\n\u90a3\u9663\u5b50\uff0c\u9910\u5ef3\u3001\u5546\u5e97\u3001\u751a\u81f3\u7fbd\u7403\u9928\u4e2d\u90fd\u7d93\u5e38\u5faa\u74b0\u64ad\u653e\u8457\u9019\u4e9b\u6b4c\u66f2\uff0c\u65bc\u662f\u6211\u7684\u8eab\u9ad4\u4f3c\u4e4e\u5c31\u5c07\u9019\u4e9b\u6b4c\u66f2\u8207\u300c2018 \u5e74\u3001\u570b\u4e2d\u300d\u7d81\u5b9a\u5728\u4e00\u8d77\uff0c\u5f80\u5f8c\u6bcf\u6b21\u807d\u898b\uff0c\u90fd\u80fd\u5920\u56de\u5230\u90a3\u500b\u6642\u7a7a\u3002\\n\\n\u7576\u6642\u6211\u7238\u7368\u81ea\u5728\u5927\u9678\u5de5\u4f5c\uff0c\u5bb6\u88e1\u53ea\u6709\u6211\u5abd\u3001\u6211\u59d0\u548c\u6211\u3002\\n\\n\u5927\u6982\u508d\u665a\u4e94\u9ede\u7b2c\u516b\u7bc0\u8ab2\u7d50\u675f\u5f8c\uff0c\u6211\u548c\u6211\u59d0\u5247\u9678\u7e8c\u56de\u5230\u5bb6\u4e2d\uff0c\u7b2c\u4e00\u4ef6\u4e8b\u662f\u4e00\u908a\u770b Youtube \u4e00\u908a\u5403\u665a\u9910\u3002\u6211\u5abd\u5176\u5be6\u4e0d\u5141\u8a31\u6211\u5011\u5403\u98ef\u6642\u770b\u5f71\u7247\uff0c\u4e0d\u904e\u5728\u9ad4\u8ad2\u6211\u5011\u5df2\u7d93\u5728\u5b78\u6821\u8f9b\u82e6\u4e00\u6574\u5929\uff0c\u5979\u9078\u64c7\u775c\u4e00\u96bb\u773c\u9589\u4e00\u96bb\u773c\uff0c\u4e0d\u6253\u64fe\u6211\u5011\u4e00\u6574\u5929\u5c11\u6578\u7684\u653e\u9b06\u6642\u9593\u3002\\n\\n\u5403\u5b8c\u98ef\u6d17\u6fa1\u5f8c\uff0c\u5c31\u5c55\u958b\u665a\u4e0a\u7684\u8b80\u66f8\u6642\u9593\u4e86\uff0c\u5305\u542b\u5beb\u4f5c\u696d\u3001\u6e96\u5099\u660e\u5f8c\u5929\u7684\u8003\u8a66\u3001\u6e96\u5099\u4e0b\u4e00\u6b21\u5927\u8003\uff08\u6bb5\u8003\u3001\u6a21\u8003\u3001\u6703\u8003\uff09\u7b49\u7b49\uff0c3-4 \u500b\u5c0f\u6642\u662f\u5e38\u614b\uff0c\u52a0\u4e0a\u4e00\u4e9b\u62d6\u62d6\u62c9\u62c9\u7684\u6642\u9593\uff0c\u4e00\u8f49\u773c\u5c31\u5230\u51cc\u6668 12 \u9ede\u4e86\u3002\u7761\u524d\u6709\u6642\u6703\u548c\u6211\u7238\u8996\u8a0a\u4e00\u4e0b\uff0c\u6216\u662f\u6ed1\u6ed1\u624b\u6a5f\u5077\u500b\u9592\uff0c\u4e0d\u80fd\u62d6\u592a\u4e45\uff0c\u56e0\u70ba\u9694\u5929 6:40 \u4ecd\u8981\u65e9\u8d77\u3002\u6bcf\u5230\u9031\u672b\uff0c\u751f\u6d3b\u624d\u80fd\u6709\u4e9b\u8a31\u8b8a\u5316\uff0c\u50cf\u662f\u51fa\u53bb\u8d70\u8d70\u6216\u5403\u500b\u98ef\u4e4b\u985e\u7684\uff0c\u4e0d\u904e\u884c\u7a0b\u9084\u662f\u633a\u55ae\u7d14\u7684\uff0c\u57fa\u672c\u4e0a\u96e2\u4e0d\u958b\u8b80\u66f8\u3001\u5beb\u529f\u8ab2\uff0c\u65e5\u5fa9\u4e00\u65e5\u3001\u9031\u5fa9\u4e00\u9031\u3002\\n\\n\\n\u4e0d\u77e5\u662f\u7576\u6642\u5e74\u7d00\u5c0f\u3001\u9084\u662f\u56e0\u70ba\u751f\u6d3b\u592a\u55ae\u7d14\uff0c14 \u6b72\u7684\u6211\u8166\u888b\u88e1\u5728\u60f3\u7684\u4e8b\u60c5\uff0c\u90fd\u662f\u4e00\u4e9b\u73fe\u5728\u770b\u4f86\u5f88\u5c0f\u7684\u4e8b\uff0c\u4f46\u8ab0\u53c8\u4e0d\u662f\u9019\u6a23\u5462\uff1f\\n\\n\u6211\u671f\u5f85\u6bcf\u9031\u4e94\u665a\u4e0a\u548c\u670b\u53cb\u5011\u4e00\u8d77\u73a9\u50b3\u8aaa\u3001\u67d0\u7bc0\u9ad4\u80b2\u8ab2\u7684\u6709\u8da3\u6d3b\u52d5\u3001\u5712\u904a\u6703\u3001\u6821\u6176\u904b\u52d5\u6703\u3001\u548c\u670b\u53cb\u5011\u8b1b\u5e79\u8a71 ; \u4e5f\u6709\u64d4\u5fc3\u7684\u4e8b\uff0c\u4f8b\u5982\u8003\u8a66\u6210\u7e3e\u3001\u67d0\u6b21\u4e0a\u53f0\u5831\u544a\u3001\u8001\u5e2b\u548c\u540c\u5b78\u5c0d\u6211\u7684\u770b\u6cd5\u3001\u8173\u5728\u6253\u7fbd\u7403\u6642\u626d\u5230\u4e86\u3001\u60f3\u8981\u63db\u65b0\u624b\u6a5f\u3001\u60f3\u8981\u66f4\u591a\u81ea\u7531\u7b49\u7b49\u3002\\n\\n\u6578\u4e0d\u5b8c\u7684\u5c0f\u78ba\u5e78\u8207\u5c0f\u7169\u60f1\uff0c\u5145\u65a5\u8457\u90a3\u500b\u6642\u7a7a\uff0c\u4e5f\u69cb\u6210\u4e86\u6211\u7684\u9752\u6625\u3002\\n\\n\u96d6\u7136\u6211\u7684\u9752\u6625\u4e26\u6c92\u6709\u975e\u5e38\u7279\u5225\uff0c\u751a\u81f3\u9084\u6709\u4e9b\u5e73\u5e73\u7121\u5947\uff0c\u4f46\u6bcf\u6b21\u6211\u8f49\u982d\u770b\uff0c\u90a3\u90fd\u662f\u4e00\u500b\u967d\u5149\u660e\u5a9a\u3001\u6eab\u6696\u3001\u771f\u8aa0\u7684\u6642\u7a7a\u3002\\n\\n\u5982\u679c\u4f60\u4e5f\u6709\u60f3\u56de\u53bb\u7684\u6642\u7a7a\uff0c\u53bb\u807d\u807d\u90a3\u6642\u5e38\u807d\u7684\u6b4c\u5427\u3002\\n<img src=\\"/img/IMG_20191228.jpg\\" alt=\\"2019\\" width=\\"350\\" />\\n<br/>\\n<small>\u5716 : \u967d\u5149\u660e\u5a9a</small>"},{"id":"benifits-of-website","metadata":{"permalink":"/blog/benifits-of-website","source":"@site/blog/2025-11-25-why-website.md","title":"\u67b6\u500b\u4eba\u7db2\u7ad9\u7684\u4e09\u500b\u539f\u56e0","description":"\u8ac7\u8ac7\u6211\u70ba\u4ec0\u9ebc\u67b6\u7db2\u7ad9\u5beb\u90e8\u843d\u683c","date":"2025-11-25T00:00:00.000Z","tags":[],"readingTime":2.21,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"benifits-of-website","title":"\u67b6\u500b\u4eba\u7db2\u7ad9\u7684\u4e09\u500b\u539f\u56e0","authors":["tzuchun"],"date":"2025-11-25T00:00:00.000Z","description":"\u8ac7\u8ac7\u6211\u70ba\u4ec0\u9ebc\u67b6\u7db2\u7ad9\u5beb\u90e8\u843d\u683c"},"unlisted":false,"prevItem":{"title":"\u7a7f\u8d8a\u6642\u7a7a\u7684\u65b9\u6cd5","permalink":"/blog/music-time-travel"},"nextItem":{"title":"\u6700\u597d\u4e0d\u8981\u8ddf\u5927\u5bb6\u4e00\u6a23","permalink":"/blog/be-different"}},"content":"\u4f5c\u70ba\u4e00\u500b\u5927\u5b78\u751f\uff0c\u60f3\u7576\u7136\u6211\u8eab\u65c1**\u5e7e\u4e4e\u6240\u6709\u4eba\u90fd\u5728\u7528 Facebook, Instagram, Threads** \u7b49\u4e3b\u6d41\u793e\u7fa4\u5a92\u9ad4\uff0c\u9019\u8b93\u67b6\u500b\u4eba\u7db2\u7ad9\u3001\u5beb\u90e8\u843d\u683c\u986f\u5f97\u6709\u9ede\u300c\u975e\u4e3b\u6d41\u300d\uff0c\u751a\u81f3\u4e0d\u77e5\u9053\u5728\u505a\u4ec0\u9ebc\uff0c\u4f46\u70ba\u4ec0\u9ebd\u6211\u8981\u9019\u9ebc\u505a\uff1f\\n\\n\u7c21\u55ae\u4f86\u8aaa\uff0c\u6709\u4e09\u500b\u539f\u56e0\u3002\\n\\n### \u4e00\u3001\u53d7\u5230 Wiwi \u555f\u767c\\n\\n\u4e0d\u77e5\u9053\u662f\u4e0d\u662f\u6211\u8a18\u932f\u4e86\uff0c\u4f46\u6211\u597d\u50cf\u66fe\u7d93\u5728\u67d0\u96c6 [\u597d\u6ab8\u6aacPodcast](https://nicelemon.libsyn.com) \u4e2d\u807d\u904e Wiwi \u8aaa\uff1a\u300c\u62dc\u8a17\uff0c\u6211\u570b\u4e2d\u7684\u6642\u5019\u6211\u5011\u6bcf\u500b\u73ed\u5c31\u90fd\u6709\u81ea\u5df1\u7684\u90e8\u843d\u683c\u7db2\u7ad9\u4e86...\u300d\uff0c\u9019\u53e5\u8a71\u5be6\u5728\u8b93\u6211\u610f\u8b58\u5230\u81ea\u5df1\u9700\u8981\u591a\u9032\u6b65\u4e86\u3002\\n\\n    \u6642\u4ee3\u4e0d\u65b7\u66f4\u8fed\uff0c\u5728 2025 \u5e74\u7684\u4eca\u5929\uff0c\u8cc7\u8a0a\u53d6\u5f97\u5df2\u76f8\u7576\u5bb9\u6613\u3001\u751a\u81f3\u9084\u6709 AI \u5e6b\u5fd9\u6253\u7a0b\u5f0f\uff0c\u81ea\u5df1\u67b6\u4e00\u500b\u7db2\u7ad9\u4e0d\u61c9\u8a72\u662f\u96e3\u4e8b\u3002\u5148\u4e0d\u8ac7\u9084\u8981\u4e0d\u8981\u4f7f\u7528\u4e3b\u6d41\u793e\u7fa4\u5a92\u9ad4\uff0c\u4f46\u6211\u5e0c\u671b\u81ea\u5df1**\u81f3\u5c11\u64c1\u6709\u5e7e\u500b\u4e3b\u6d41\u793e\u7fa4\u5a92\u9ad4\u4ee5\u5916\u7684\u300c\u9078\u64c7\u300d\uff0c\u800c\u500b\u4eba\u7db2\u7ad9\u6b63\u597d\u6eff\u8db3\u4e86\u9019\u500b\u9700\u6c42**\u3002\\n\\n### \u4e8c\u3001\u6211\u7684\u6587\u7b46\u5927\u5e45\u9000\u6b65\\n\\n\u904e\u53bb\u4e00\u5169\u5e74\u7fd2\u6163\u4f7f\u7528 ChatGPT \u751f\u6210\u5404\u7a2e\u6587\u5b57\u5f8c\uff0c\u7576\u5931\u53bb AI \u7684\u8f14\u52a9\uff0c\u6211\u767c\u73fe\u81ea\u5df1\u7adf\u7136\u5beb\u4e0d\u51fa\u6eff\u610f\u7684\u6587\u7ae0\uff0c\u6216\u662f\u7368\u7acb\u5beb\u4f5c\u6240\u9700\u7684\u6642\u9593\u6bd4\u4ee5\u5f80\u9084\u8981\u9577\u4e86\u975e\u5e38\u591a\u3002\\n\\n\u9019\u6a23\u7684\u72c0\u6cc1\u771f\u7684\u6709\u5687\u5230\u6211\uff0c\u56e0\u70ba\u6211\u975e\u5e38\u76f8\u4fe1\u5beb\u4f5c\u662f\u601d\u8003\u7684\u5c55\u73fe\uff0c\u7576\u5beb\u4f5c\u51fa\u4e86\u554f\u984c\uff0c\u6211\u7684\u601d\u8003\u80af\u5b9a\u4e5f\u51fa\u554f\u984c\u4e86\u3002\u5f15\u7528\u4e00\u53e5\u79d1\u5b78\u5bb6 Leslie Lamport \u6240\u8aaa\u7684\u300c**\u4e0d\u5beb\u4f5c\u7684\u601d\u8003\u4e0d\u662f\u601d\u8003\uff0c\u53ea\u662f\u81ea\u4ee5\u70ba\u6709\u5728\u601d\u8003**\u300d\uff0c\u800c\u6211\u78ba\u5b9a\u81ea\u5df1\u4e0d\u60f3\u5931\u53bb\u601d\u8003\u7684\u80fd\u529b\uff0c\u6240\u4ee5\u6211\u5fc5\u9808\u958b\u59cb\u91cd\u65b0\u7df4\u7fd2\u5beb\u4f5c\u4e86\u3002\\n\\n\u65bc\u662f\u6211\u5c31\u958b\u59cb\u5beb\u90e8\u843d\u683c\u3001\u4e26\u4e14\u5f88\u6709\u610f\u8b58\u7684\u63a7\u5236\u81ea\u5df1\u4f7f\u7528 AI \u5beb\u4f5c\u3002\\n\\n### \u4e09\u3001\u6e1b\u5c11\u4f7f\u7528\u793e\u7fa4\u8edf\u9ad4\\n\\n\u5df2\u7d93\u6709\u4e0d\u5c11\u7814\u7a76\u8b49\u5be6\u793e\u7fa4\u5a92\u9ad4\u6703**\u6545\u610f\u8a2d\u8a08\u6210\u8b93\u4eba\u4e0a\u766e\u4e86**\uff0c\u9019\u662f\u4e00\u4ef6\u5f88\u8b8a\u614b\u7684\u4e8b\u60c5\u3002\\n\\n\u540c\u6642\uff0c\u6211**\u9ad4\u611f\u4e0a\u4e5f\u89ba\u5f97\u4f7f\u7528\u793e\u7fa4\u5a92\u9ad4\u6c92\u6709\u592a\u591a\u597d\u8655**\uff0c\u6709\u6642\u807d\u5230\u65c1\u4eba\u5728\u8a0e\u8ad6\u4e00\u4e9b\u7576\u4e0b\u71b1\u9580\u7684\u6642\u4e8b\u3001\u77ed\u5f71\u7247\u3001\u751a\u81f3\u4efb\u4f55\u5947\u5947\u602a\u602a\u7684\u4e8b\u60c5\uff0c\u800c\u6211\u537b\u5f9e\u4f86\u6c92\u770b\u904e\u6216\u807d\u904e\uff0c\u53cd\u800c\u9084\u6703**\u6709\u4e00\u7a2e\u6e05\u975c\u611f\u548c\u6176\u5e78\u611f**\u3002\\n\\n\u6700\u5f8c\u6211\u4e5f\u9700\u8981\u7bc0\u7701\u6642\u9593\u548c\u7cbe\u529b\u3002\u6211\u8a8d\u70ba\u6211\u7684\u751f\u6d3b\u5df2\u7d93\u76f8\u7576\u7c21\u55ae\u4e86\uff0c\u537b\u9084\u662f\u60f3\u8981\u6709\u66f4\u591a\u6642\u9593\u505a\u6709\u610f\u7fa9\u7684\u4e8b\u60c5\u3002\u76ee\u524d\u6211\u5df2\u7d93\u5e7e\u4e4e**\u6210\u529f\u907f\u958b\u4efb\u4f55\u300c\u6f14\u7b97\u6cd5\u63a8\u85a6\u300d\u7684\u5167\u5bb9\u4e86**\uff0c\u6211\u76e1\u91cf\u53ea\u770b\u81ea\u5df1\u8a02\u95b1\u7684\u6587\u7ae0\uff0c\u6216\u662f\u81ea\u5df1\u641c\u5c0b\u7684\u5f71\u7247\uff08\u7576\u7136\u5973\u53cb\u4e0d\u7ba1\u50b3\u4ec0\u9ebc\u7d66\u6211\uff0c\u6211\u90fd\u9084\u662f\u6703\u770b\uff09\uff0c\u9019\u6a23\u505a\u78ba\u5be6\u5e6b\u6211\u7701\u4e0b\u4e0d\u5c11\u6642\u9593\uff0c\u6210\u6548\u883b\u597d\u7684\u3002\\n\\n\u4ee5\u524d\u5728\u516c\u8eca\u4e0a\u53ef\u80fd\u5728\u6ed1\u77ed\u5f71\u7247\u4e4b\u985e\u7684\uff0c\u73fe\u5728\u5c31\u53ea\u80fd\u8a8d\u771f\u770b\u5831\u544a\u56c9\u3002"},{"id":"be-different","metadata":{"permalink":"/blog/be-different","source":"@site/blog/2025-11-18-be-different.md","title":"\u6700\u597d\u4e0d\u8981\u8ddf\u5927\u5bb6\u4e00\u6a23","description":"\u5ffd\u7136\u60f3\u5230\u4ee5\u524d\u570b\u4e2d\u5beb\u4f5c\u6587\u7684\u6642\u5019...","date":"2025-11-18T00:00:00.000Z","tags":[],"readingTime":1.63,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"be-different","title":"\u6700\u597d\u4e0d\u8981\u8ddf\u5927\u5bb6\u4e00\u6a23","authors":["tzuchun"],"description":"\u5ffd\u7136\u60f3\u5230\u4ee5\u524d\u570b\u4e2d\u5beb\u4f5c\u6587\u7684\u6642\u5019..."},"unlisted":false,"prevItem":{"title":"\u67b6\u500b\u4eba\u7db2\u7ad9\u7684\u4e09\u500b\u539f\u56e0","permalink":"/blog/benifits-of-website"},"nextItem":{"title":"\u628a\u4e8b\u60c5\u641e\u5b9a","permalink":"/blog/get-things-done"}},"content":"\u300c\u6700\u597d\u4e0d\u8981\u8ddf\u5225\u4eba\u4e00\u6a23\u300d\\n\\n\u7b2c\u4e00\u6b21\u6709\u9019\u500b\u5ff5\u982d\uff0c\u61c9\u8a72\u662f\u570b\u4e2d\u7df4\u7fd2\u5beb\u4f5c\u6587\u7684\u6642\u5019\u3002\u7576\u6642\u6bcf\u6b21\u62ff\u5230\u4f5c\u6587\u8003\u5377\u5f8c\uff0c\u53ea\u8981\u662f\u60f3\u5230\u7684\u524d\u4e09\u500b\u60f3\u6cd5\uff0c\u6211\u90fd\u4e00\u5b9a\u4e0d\u6703\u5beb\u3002**\u4e26\u4e0d\u662f\u8aaa\u6211\u5f88\u6709\u81ea\u4fe1\u80fd\u5beb\u51fa\u4ec0\u9ebc\u7279\u5225\u7684\u6587\u7ae0\uff0c\u53cd\u800c\u662f\u6211\u6c92\u81ea\u4fe1\u6709\u8fa6\u6cd5\u5beb\u5f97\u6bd4\u5225\u4eba\u597d**\u3002\\n\\n\u6211\u7e3d\u89ba\u5f97\uff0c\u8981\u662f\u8ddf\u5927\u5bb6\u5beb\u5dee\u4e0d\u591a\u7684\u4e3b\u984c\uff0c\u90a3\u6211\u7684\u4f5c\u6587\u61c9\u8a72\u5c31\u88ab\u6df9\u6c92\u5728\u5176\u4ed6\u4e00\u767e\u500b\u985e\u4f3c\u7684\u6587\u7ae0\u4e2d\u4e86\u5427\uff0c\u800c\u4e14\u8a55\u5be9\u8001\u5e2b\u770b\u4e86\u4e00\u5806\u4e00\u6a23\u7684\u4e3b\u984c\uff0c\u4e00\u5b9a\u90fd\u770b\u5230\u53ad\u7169\u4e86\u3002\u6240\u4ee5\u62ff\u5230\u4f5c\u6587\u984c\u76ee\u5f8c\uff0c\u6211\u90fd\u6703\u76e1\u91cf\u5beb\u4e00\u500b\u6bd4\u8f03\u7279\u5225\u7684\u4e3b\u984c\u3002\\n\\n\u9019\u500b\u7b56\u7565\u5728\u7576\u6642\u633a\u7ba1\u7528\u7684\uff0c\u6240\u4ee5\u6211\u4e5f\u4e00\u76f4\u6cbf\u7528\u5230\u4eca\u5929\uff0c\u4e26\u4e14\u64f4\u6563\u5230\u5404\u500b\u65b9\u9762\u3002**\u7576\u6211\u60f3\u8981\u8b93\u5225\u4eba\u5370\u8c61\u6df1\u523b\u7684\u6642\u5019\uff0c\u6211\u90fd\u6703\u523b\u610f\u7684\u53bb\u63e3\u6469\u300c\u5225\u4eba\u6703\u600e\u9ebc\u505a\u300d\uff0c\u7136\u5f8c\u7279\u5730\u505a\u4e00\u9ede\u4e0d\u4e00\u6a23\u7684\u4e8b**\u3002\\n\\n\u4f8b\u5982\uff1a\\n- \u9762\u8a66\u7684\u81ea\u6211\u4ecb\u7d39\u8981\u8b1b\u4ec0\u9ebc\\n- \u5831\u544a\u4e2d\u7684\u89c0\u9ede\\n- \u4e0a\u53f0\u767c\u8868\u6642\u7684\u8a9e\u901f\\n- \u5403\u5348\u9910\u7684\u6642\u9593\uff08\uff1f\uff09\uff08\u907f\u958b\u4eba\u6f6e\uff09\\n\\n\u4ee5\u5beb\u5831\u544a\u4f86\u8aac\uff0c\u5047\u8a2d\u4f60\u5beb\u4e86\u4e00\u7bc7\u8ddf\u6240\u6709\u4eba\u89c0\u9ede\u4e00\u6a21\u4e00\u6a23\u7684\u5831\u544a\uff0c\u90a3\u8b80\u8005\u770b\u4e86\uff0c\u4e0d\u5c31\u6839\u672c\u7b49\u65bc\u6c92\u770b\u55ce\uff1f\u6240\u4ee5\uff0c\u6709\u8ddf\u7fa4\u773e\u4e0d\u4e00\u6a23\u7684\u5730\u65b9\uff0c\u624d\u80fd\u5438\u5f15\u5230\u6ce8\u610f\u529b\uff0c\u800c\u9019\u4e9b**\u4e0d\u4e00\u6a23\u4e4b\u8655\uff0c\u4e5f\u624d\u662f\u4f60\u771f\u6b63\u6709\u50f9\u503c\u7684\u5730\u65b9**\u3002\\n\\n\u6211\u751a\u81f3\u6703\u5c07\u4e00\u4e9b\u7121\u50b7\u5927\u96c5\u7684\u5c0f\u7f3a\u9ede\u8996\u70ba\u512a\u9ede\uff0c\u4f8b\u5982\u5c0f\u5c0f\u7684\u7d50\u5df4\u3001\u6709\u9ede\u5bb9\u6613\u5c37\u5c2c\u3001\u6709\u6642\u5019\u6709\u9ede\u7b28\u4e4b\u985e\u7684\uff08\u4f46\u524d\u63d0\u662f\u8981\u8a0e\u559c\uff09\u3002\u9019\u4e9b**\u5c0f\u7f3a\u9ede\u90fd\u662f\u589e\u52a0\u500b\u4eba\u7279\u8272\u7684\u597d\u6a5f\u6703**\uff0c\u6709\u8fa6\u6cd5\u8b93\u5225\u4eba\u5c0d\u4f60\u7a0d\u5fae\u6709\u9ede\u5370\u8c61\u3002\u5c0d\uff0c\u53ea\u662f\u300c\u7a0d\u5fae\u6709\u9ede\u5370\u8c61\u300d\u800c\u5df2\uff0c\u7562\u7adf\u5728\u4e0a\u767e\u4eba\u4e2d\uff0c\u6709\u6642\u80fd\u88ab\u8a18\u5f97\u6709\u9019\u500b\u4eba\uff0c\u5c31\u4e0d\u7c21\u55ae\u4e86\u3002\\n\\n\u6240\u4ee5\u627e\u51fa\u81ea\u5df1\u8ddf\u5225\u4eba\u4e0d\u4e00\u6a23\u7684\u5730\u65b9\uff0c\u7136\u5f8c\u5584\u7528\u5b83\u5427\u3002\\n\\n<img src=\\"/blogimg/jogging.jpeg\\" alt=\\"\u6563\u6b65\\" width=\\"300\\" />\\n<br/>\\n<small>\u5716 : \u4eca\u5929\u5728\u6cb3\u6ff1\u6563\u6b65\u62cd\u7684\uff0c\u61c9\u8a72\u53ef\u4ee5\u7a31\u4f5c\u6563\u6b65\u5716</small>"},{"id":"get-things-done","metadata":{"permalink":"/blog/get-things-done","source":"@site/blog/2025-11-13-get-things-done.md","title":"\u628a\u4e8b\u60c5\u641e\u5b9a","description":"\u91cf\u5316\u4ea4\u6613\u516c\u53f8 CEO \u7d66\u6211\u7684\u7b54\u8986","date":"2025-11-13T00:00:00.000Z","tags":[],"readingTime":2.01,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"get-things-done","title":"\u628a\u4e8b\u60c5\u641e\u5b9a","authors":["tzuchun"],"description":"\u91cf\u5316\u4ea4\u6613\u516c\u53f8 CEO \u7d66\u6211\u7684\u7b54\u8986"},"unlisted":false,"prevItem":{"title":"\u6700\u597d\u4e0d\u8981\u8ddf\u5927\u5bb6\u4e00\u6a23","permalink":"/blog/be-different"},"nextItem":{"title":"\u6295\u5165\u5927\u87a2\u5e55\u7684\u61f7\u62b1","permalink":"/blog/big-screen"}},"content":"\u6211\u5011\u793e\u5718\u6bcf\u9031\u90fd\u6703\u8209\u884c\u4e00\u6b21\u793e\u8ab2\u3002\u672c\u9031\u7684\u4e3b\u984c\u662f\u91cf\u5316\u4ea4\u6613\uff0c\u65bc\u662f\u6211\u5011\u627e\u4e86\u4e00\u4f4d\u73fe\u8077\u7684\u91cf\u5316\u4ea4\u6613\u54e1\u4f86\u5206\u4eab\uff0c\u4e0a\u534a\u5834\u7531\u8b1b\u5e2b\u4ee5\u7c21\u5831\u8b1b\u89e3\uff0c\u800c\u4e0b\u534a\u5802\u5247\u662f\u81ea\u7531\u554f\u7b54\u6642\u9593\u3002\\n\\n\u6211\u6ce8\u610f\u5230\u8a31\u591a\u540c\u5b78\u90fd\u53ea\u807d\u4e0a\u534a\u5802\u7684\u90e8\u5206\uff0c\u4e0b\u534a\u5802\u6c7a\u5b9a\u63d0\u65e9\u96e2\u958b\uff0c\u7565\u904e Q&A \u7684\u74b0\u7bc0\u3002\u4e0d\u904e\u6211\u53cd\u800c\u89ba\u5f97\uff0c**\u6bd4\u8d77\u8b1b\u5e2b\u7684\u7c21\u5831\uff0c\u771f\u6b63\u7684\u7cbe\u9ad3\u662f\u85cf\u5728\u554f\u7b54\u7576\u4e2d\u7684**\u3002\u9019\u500b\u6642\u9593\u53ef\u4ee5\u76e1\u60c5\u5730\u628a\u81ea\u5df1\u7684\u554f\u984c\u62cb\u7d66\u8b1b\u5e2b\uff0c\u4e5f\u7d93\u5e38\u53ef\u4ee5\u7372\u5f97\u5f9e\u4f86\u6c92\u60f3\u904e\u7684\u770b\u6cd5\u6216\u6d1e\u5bdf\u3002\\n\\n\u5e78\u904b\u7684\u662f\uff0c\u6628\u5929\u9664\u4e86\u4ea4\u6613\u54e1\uff0c\u516c\u53f8\u7684 CEO \u4e5f\u4f86\u5230\u4e86\u73fe\u5834\uff0c\u4e26\u4e14\u9858\u610f\u4e0a\u53f0\u56de\u7b54\u5341\u500b\u554f\u984c\u3002\\n\\n\u65bc\u662f\u6211\u554f\u4ed6\uff1a\u300c\u4ec0\u9ebc\u6a23\u7684\u9762\u8a66\u8005\u6216\u5be6\u7fd2\u751f\u80fd\u8b93\u4f60\u5370\u8c61\u6df1\u523b\uff1f\u300d\\n\\n\u4ed6\u7684\u7b54\u8986\u7c21\u5316\u5f8c\u662f\u9019\u6a23\u7684\uff1a\\n\\n> \u66fe\u7d93\u6709\u4e00\u500b\u9762\u8a66\u8005\u4f86\u9762\u8a66\u91cf\u5316\u4ea4\u6613\u54e1\uff0c\u4f46\u5b8c\u5168\u4e0d\u6703\u5beb\u7a0b\u5f0f\u3002\u7576\u6642\u6211\u5011\u57fa\u65bc\u4ed6\u67d0\u4e9b\u65b9\u9762\u9084\u883b\u6709\u71b1\u5ff1\u7684\uff0c\u6240\u4ee5\u6c7a\u5b9a\u9304\u53d6\u4ed6\u3002\\n>\u4ed6\u4e00\u958b\u59cb\u7684\u80fd\u529b\u78ba\u5be6\u505a\u4e0d\u51fa\u5c08\u6848\uff0c\u4f46\u6211\u5011\u7d66\u4ed6\u4e00\u500b\u6708\u7684\u6642\u9593\u908a\u505a\u908a\u5b78\uff0c\u4e00\u6b65\u6b65\u60f3\u8fa6\u6cd5\u628a\u5c08\u6848\u505a\u51fa\u4f86\u3002\u6700\u5f8c\u4ed6\u5c31\u771f\u7684\u53ea\u82b1\u4e86\u4e00\u500b\u6708\uff0c\u5f9e\u96f6\u958b\u59cb\u6210\u529f\u5b8c\u6210\u4e86\u90a3\u500b\u5c08\u6848...\\n>\\n>\u6240\u4ee5...\u6211\u60f3\u5982\u679c\u80fd\u8b93\u6211\u611f\u89ba\u300c**\u4f60\u6709\u8fa6\u6cd5\u628a\u4e8b\u60c5\u641e\u5b9a**\u300d\uff0c\u6211\u5c31\u6703\u5c0d\u4f60\u5370\u8c61\u6df1\u523b\u3002\u4e5f\u8a31\u4f60\u73fe\u5728\u80fd\u529b\u9084\u4e0d\u884c\uff0c\u90a3\u4e00\u500b\u6708\u5f8c\u884c\u4e0d\u884c\uff1f\u5169\u500b\u6708\u5f8c\u884c\u4e0d\u884c\uff1f \u6211\u5011\u8981\u7684\u662f\u80fd\u641e\u5b9a\u4e8b\u60c5\u7684\u4eba\u3002\\n\\nCEO \u7684\u9019\u500b\u7b54\u8986\u5c0d\u6211\u4f86\u8b1b\u883b\u6709\u555f\u767c\u6027\u7684\uff0c\u5b8c\u5168\u53ef\u4ee5\u7406\u89e3\u4e00\u500b**\u6709\u8fa6\u6cd5\u4e0d\u65b7\u9032\u6b65\u3001\u64f4\u5c55\u80fd\u529b\u5708\u7684\u54e1\u5de5\uff0c\u8207\u6c92\u6709\u81ea\u884c\u5b78\u7fd2\u601d\u8003\u80fd\u529b\u7684\u54e1\u5de5\u5dee\u8ddd\u6709\u591a\u5927**\u3002\u7576\u6642\u9593\u62c9\u9577\uff0c\u66f4\u662f\u5929\u8207\u5730\u7684\u5dee\u5225\u4e86\u3002\\n\\n\u56de\u5230\u81ea\u5df1\u8eab\u4e0a\uff0c\u9664\u4e86\u4fdd\u6301\u6bcf\u5929\u9032\u6b65\u4e00\u9ede\u9ede\u7684\u7fd2\u6163\uff0c\u4e5f\u8457\u624b\u601d\u8003\u5982\u4f55\u5728\u9762\u8a66\u4e2d\u4ee5\u7c21\u55ae\u7684\u65b9\u5f0f\u5c55\u73fe\u9019\u500b\u80fd\u529b\uff0c\u6211\u76ee\u524d\u89ba\u5f97\u300c\u8aaa\u6545\u4e8b\u300d\u6703\u662f\u4e0d\u932f\u7684\u65b9\u5f0f\u3002\u7576\u6211\u5011**\u4ee5\u6545\u4e8b\u5448\u73fe\u81ea\u5df1\u904e\u53bb\u9762\u5c0d\u672a\u77e5\u4e8b\u7269\u7684\u89c0\u9ede\u3001\u63a1\u53d6\u7684\u5b78\u7fd2\u65b9\u5f0f\uff0c\u4ee5\u53ca\u6700\u5f8c\u7684\u6210\u9577\u66f2\u7dda\u8207\u6210\u679c**\uff0c\u61c9\u8a72\u5c31\u8db3\u4ee5\u8b93\u9762\u8a66\u5b98\u5c0d\u6211\u5011\u300c\u628a\u4e8b\u60c5\u641e\u5b9a\u300d\u7684\u80fd\u529b\u6709\u591a\u4e00\u9ede\u4e86\u89e3\uff0c\u4e26\u5851\u9020\u4e00\u500b\u66f4\u7acb\u9ad4\u7684\u500b\u4eba\u5f62\u8c61\u4e86\u5427\u3002\\n\\n:::tip[\u66f4\u591a\u9762\u8a66\u76f8\u95dc\u8a0e\u8ad6]\\n\u5982\u679c\u5c0d\u300c\u9762\u8a66\u300d\u9019\u500b\u8a71\u984c\u6709\u8208\u8da3\uff0c[\u9019\u7bc7\u6587\u7ae0](/docs/knowledge-interview)\u6709\u66f4\u6df1\u5165\u7684\u8a0e\u8ad6\u9762\u8a66\u6280\u5de7\u3002\\n:::"},{"id":"big-screen","metadata":{"permalink":"/blog/big-screen","source":"@site/blog/2025-11-11-big-screen.md","title":"\u6295\u5165\u5927\u87a2\u5e55\u7684\u61f7\u62b1","description":"\u4f7f\u7528\u5927\u87a2\u5e55\u7684\u512a\u9ede\u7c21\u76f4\u8aaa\u4e0d\u5b8c","date":"2025-11-11T00:00:00.000Z","tags":[],"readingTime":1.96,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"big-screen","title":"\u6295\u5165\u5927\u87a2\u5e55\u7684\u61f7\u62b1","authors":["tzuchun"],"description":"\u4f7f\u7528\u5927\u87a2\u5e55\u7684\u512a\u9ede\u7c21\u76f4\u8aaa\u4e0d\u5b8c","rss":true},"unlisted":false,"prevItem":{"title":"\u628a\u4e8b\u60c5\u641e\u5b9a","permalink":"/blog/get-things-done"},"nextItem":{"title":"\u6709\u50f9\u503c\u7684\u6771\u897f","permalink":"/blog/value-post"}},"content":"\u4eca\u5e74\u6c7a\u5b9a\u9001\u5973\u53cb\u4e00\u500b\u5916\u63a5\u87a2\u5e55\u7576\u751f\u65e5\u79ae\u7269\uff0c\u61c9\u8a72\u662f\u4e00\u500b\u76f8\u7576\u5be6\u7528\u7684\u79ae\u7269\uff0c\u5979\u4e5f\u883b\u559c\u6b61\u7684\u3002\u4e0d\u904e**\u4f7f\u7528\u5916\u63a5\u87a2\u5e55\u7684\u512a\u9ede\u5be6\u5728\u592a\u591a\u4e86**\uff0c\u6211\u4e0d\u5f97\u4e0d\u5728\u9019\u908a\u628a\u5b83\u5beb\u4e0b\u4f86\uff01\\n\\n\u5148\u804a\u804a\u7528\u7b46\u96fb\u87a2\u5e55\u7684\u554f\u984c\u3002\\n\\n\u4e0d\u5916\u4e4e\u5c31\u662f\u87a2\u5e55\u592a\u5c0f\u4e86\uff0c\u6240\u4ee5\u5167\u5bb9\u7121\u6cd5\u653e\u5927\uff0c\u4e26\u4e14\u56e0\u70ba\u53ea\u6709\u4e00\u500b\u87a2\u5e55\uff0c\u7576\u4f60\u8981\u958b\u555f\u591a\u500b\u8996\u7a97\u6642\uff0c\u5f97\u628a\u539f\u672c\u5c31\u4e0d\u5927\u7684\u87a2\u5e55\u5207\u5272\u6210\u66f4\u5c0f\u7684\u683c\u5b50\uff0c\u6216\u662f\u983b\u7e41\u7684\u5207\u63db\u8996\u7a97\u3002\\n\\n\u9019\u6a23\u6703\u5e36\u4f86\u5169\u500b\u8ca0\u9762\u5f71\u97ff\uff1a\\n- **\u9020\u6210\u8a18\u61b6\u8ca0\u8377**\uff1a\u5728\u4f7f\u7528\u7b46\u96fb\u87a2\u5e55\u6642\uff0c\u4e00\u500b\u8996\u7a97\u53ef\u4ee5\u986f\u793a\u7684\u5167\u5bb9\u5f88\u6709\u9650\uff0c\u6240\u4ee5\u4f7f\u7528\u8005\u5f80\u5f80\u5f97\u300c\u5148\u8a18\u8457\u4e00\u6bb5\u8a0a\u606f\u300d\uff0c\u518d\u300c\u63a5\u8457\u770b\u4e0b\u4e00\u6bb5\u300d\u3002\u9019\u6a23\u6703\u9020\u6210\u5927\u8166\u984d\u5916\u7684\u8ca0\u64d4\uff0c\u7121\u6cd5\u5c07\u7cbe\u529b\u5168\u90e8\u7528\u5728\u7406\u89e3\u5167\u5bb9\uff0c\u6700\u7d42\u5c0e\u81f4\u7406\u89e3\u6210\u6548\u8b8a\u5dee\u3002\\n- **\u9700\u8981\u983b\u7e41\u5207\u63db\u8996\u7a97**\uff1a\\n    Microsoft Research\uff08Mark et al., 2005\uff09\u9577\u671f\u8ffd\u8e64\u77e5\u8b58\u5de5\u4f5c\u8005\u5f8c\u767c\u73fe\uff1a\u4eba\u5011\u5e73\u5747\u6bcf 3 \u5206\u9418\u5c31\u5207\u63db\u4e00\u6b21\u8996\u7a97\u6216\u61c9\u7528\u7a0b\u5f0f\u3002\u800c\u6bcf\u6b21\u4e2d\u65b7\u5f8c\uff0c\u9700\u8981\u8d85\u904e 20 \u5206\u9418 \u624d\u80fd\u5b8c\u5168\u6062\u5fa9\u539f\u672c\u7684\u5c08\u6ce8\u72c0\u614b\uff0c\u610f\u601d\u662f\uff0c\u4ed6\u5011\u6839\u672c\u96a8\u6642\u90fd\u8655\u65bc\u53d7\u5e72\u64fe\u7684\u72c0\u614b\u3002\u540c\u6642\uff0c\u5927\u8166\u983b\u7e41\u88ab\u4e2d\u65b7\u53c8\u91cd\u555f\uff0c\u5c0d\u8166\u529b\u7684\u8017\u640d\u4e5f\u76f8\u7576\u5927\u3002\\n- **\u8996\u529b\u554f\u984c**\uff1a\u7528\u5c0f\u87a2\u5e55\uff0c\u5b57\u90a3\u9ebc\u5c0f\uff0c\u8996\u8ddd\u53c8\u8fd1\uff0c\u5f88\u50b7\u8996\u529b\u554a\u554a\u554a\uff01\\n\\n\u800c\u9019\u4e9b\u554f\u984c\uff0c\u5916\u63a5\u5927\u87a2\u5e55\u525b\u597d\u90fd\u80fd\u89e3\u6c7a\u3002\\n\\n\u4f60\u53ef\u4ee5\u628a\u8996\u7a97\u653e\u5728\u4e0d\u540c\u7684\u87a2\u5e55\u4e0a\uff0c\u6bcf\u4e00\u500b\u90fd**\u80fd\u4ee5\u8212\u670d\u7684\u5927\u5c0f\uff0c\u6e05\u6670\u5730\u986f\u793a\u51fa\u4f86**\u3002\u7576\u4f60\u60f3\u8981\u53c3\u8003\u591a\u500b\u5167\u5bb9\u6642\uff0c\u4e5f\u4e0d\u518d\u9700\u8981\u5207\u4f86\u5207\u53bb\uff0c\u53ea\u8981\u7a0d\u5fae\u62ac\u500b\u982d\u5c31\u53ef\u4ee5\u5c07\u6240\u6709\u8cc7\u8a0a\u4e00\u89bd\u7121\u907a\u3002\u9019\u6a23\u6d41\u66a2\u7684\u5de5\u4f5c\u6d41\u7a0b\u53ef\u4ee5**\u6700\u5927\u5316\u5de5\u4f5c\u6548\u7387\uff0c\u4e26\u6700\u5c0f\u5316\u8166\u529b\u8017\u640d\u9084\u6709\u904e\u7a0b\u4e2d\u7684\u7126\u8e81\u611f**\u3002\\n\\n\u4e0a\u8ff0\u7684\u597d\u8655\u5df2\u7d93\u88ab\u7814\u7a76\u8b49\u5be6\u4e86\uff0c\u5f9e Dell \u7684\u7814\u7a76\u5831\u544a\u4e2d\u53ef\u898b\uff0c\u53ea\u8981\u7528\u7b46\u96fb\u642d\u914d\u4e00\u500b 25-32 \u540b\u7684\u5916\u63a5\u87a2\u5e55\uff0c**\u5c31\u53ef\u4ee5\u8b93\u751f\u7522\u529b\u63d0\u5347 30% \u4ee5\u4e0a**\uff0c\u5982\u679c\u4f60\u7528 40 \u540b\u4ee5\u4e0a\u7684\u87a2\u5e55\uff0c\u751a\u81f3\u53ef\u4ee5\u63d0\u5347 43% \u7684\u751f\u7522\u529b\u3002\\n\\n![Dell\u8cc7\u6599](/blogimg/screentime.png)\\n<small>\u5716 : \u4e0d\u540c\u5927\u5c0f\u5916\u63a5\u87a2\u5e55\u6240\u80fd\u63d0\u5347\u7684\u751f\u7522\u529b</small>\\n\\n\u7e3d\u4e4b\uff0c\u6211\u89ba\u5f97\u9019\u662f\u4e00\u500b\u5f88\u68d2\u7684\u6295\u8cc7\u3002\u4e0d\u7528\u4e09\u5343\u584a\u5c31\u53ef\u4ee5\u8cb7\u5230\u4e00\u7247\u5e36\u6709\u8b77\u773c\u529f\u80fd\u7684\u87a2\u5e55\uff0c\u9084\u80fd\u8b93\u4ee5\u5f8c\u5de5\u4f5c\u6548\u7387\u66f4\u9ad8\u3001\u5927\u8166\u66f4\u8f15\u9b06\u3002\\n\\n\u6709\u5920\u5212\u7b97\u3002"},{"id":"value-post","metadata":{"permalink":"/blog/value-post","source":"@site/blog/2025-11-04-value.md","title":"\u6709\u50f9\u503c\u7684\u6771\u897f","description":"\u6574\u7406\u76f8\u7247\u6642\u60f3\u5230\u7684...","date":"2025-11-04T00:00:00.000Z","tags":[],"readingTime":1.14,"hasTruncateMarker":false,"authors":[{"name":"TzuChun Chao","title":"Blog Owner","socials":{"Facebook":"https://www.facebook.com/max.chao.33/","email":"mailto:tzuchun11232004@gmail.com"},"imageURL":"/img/author.JPG","key":"tzuchun","page":null}],"frontMatter":{"slug":"value-post","title":"\u6709\u50f9\u503c\u7684\u6771\u897f","authors":["tzuchun"],"description":"\u6574\u7406\u76f8\u7247\u6642\u60f3\u5230\u7684..."},"unlisted":false,"prevItem":{"title":"\u6295\u5165\u5927\u87a2\u5e55\u7684\u61f7\u62b1","permalink":"/blog/big-screen"}},"content":"\u4eca\u5929\u70ba\u4e86\u9a30\u51fa\u4e00\u9ede\u5132\u5b58\u7a7a\u9593\uff0c\u9700\u8981\u522a\u9664\u4e00\u4e9b\u5f71\u7247\u3002  \\n\\n\u9019\u500b\u6d41\u7a0b\u6211\u7d93\u6b77\u904e\u597d\u5e7e\u6b21\u4e86\uff0c\u5728\u4e00\u767e\u500b\u591a\u7279\u5225\u5927\u7684\u6a94\u6848\u4e2d\u4f86\u56de\u7ffb\u95b1\uff0c\u8a66\u5716\u627e\u51fa\u4e00\u500b\u7576\u6642\u53ea\u662f\u4e0d\u5c0f\u5fc3\u5b58\u5230\u7684\u5f71\u7247\uff0c\u6216\u4e0d\u91cd\u8981\u7684\u6a94\u6848\u3002\\n\\n\u5728\u904e\u7a0b\u4e2d\u6211\u767c\u73fe\uff0c\u6709\u4e9b\u6a94\u6848\u6211**\u5f9e\u4e0d\u8003\u616e\u522a\u9664\u5b83\u5011**\uff0c\u800c\u5b83\u5011\u5927\u6982\u6709\u5e7e\u500b\u7279\u9ede\u3002\\n* \u6211\u5bb6\u5c0f\u72d7\u7684\u9304\u5f71\\n* \u5bb6\u4eba\u7684\u9304\u5f71\u3001\u9304\u97f3\\n* \u67d0\u6bb5\u6642\u9593\u7684\u751f\u6d3b\u7d00\u9304\uff08\u7279\u5225\u662f\u6bd4\u8f03\u591a\u5e74\u524d\u7684\uff09\\n\\n\u800c\u90a3\u4e9b**\u88ab\u522a\u9664\u7684**\u5462\uff1f \u6211\u9078\u64c7\u522a\u9664\u4e86...\\n* \u6f14\u5531\u6703\u9304\u8d77\u4f86\u767c\u793e\u7fa4\u7684\u5f71\u7247\\n* \u4e00\u4e9b\u98a8\u666f\u7f8e\u7167\\n* \u5de5\u4f5c\u9700\u8981\u800c\u9304\u4e0b\u7684\u7247\u6bb5\\n\\n**\u88ab\u6211\u522a\u9664\u7684**\u6a94\u6848\u6709\u4e00\u500b\u5171\u540c\u6027\u8cea\uff0c\u5b83\u5011\u5f88\u5927\u6a5f\u7387\u662f\u300c**\u7d66\u5225\u4eba\u770b\u7684**\u300d\uff0c\u4f8b\u5982\u767c\u5230\u793e\u7fa4\u6216\u5206\u4eab\u7d66\u670b\u53cb\u3002\u4f46\u7576\u6642\u9593\u62c9\u9060\uff0c\u6211\u6839\u672c\u4e0d\u60f3\u8981\u4fdd\u5b58\u54ea\u500b\u7576\u7d05\u660e\u661f\u7684 Live \u5f71\u7247\uff0c\u6216\u67d0\u4e9b\u5f88\u7f8e\u7684\u98a8\u666f\u7167\u3002\\n\\n\u76f8\u53cd\u7684\uff0c\u90a3\u4e9b\u6211**\u5f9e\u4e0d\u8003\u616e\u522a\u9664\u7684**\u5f71\u7247\u5e7e\u4e4e\u4e0d\u66fe\u8ddf\u8ab0\u5206\u4eab\u904e\uff0c\u56e0\u70ba\u6211\u4e0d\u5fc5\u9019\u9ebc\u505a\u3002\u5b83\u5011\u6536\u9304\u8457\u6211\u91cd\u8981\u7684\u67d0\u6bb5\u751f\u6d3b\u3001\u67d0\u500b\u5c0d\u8a71\u3001\u6216\u662f\u67d0\u4e9b\u4eba\uff0c\u800c\u9019\u4e9b\u5f71\u7247\u300c**\u662f\u7d66\u6211\u81ea\u5df1\u770b\u7684**\u300d\uff0c\u9019\u6a23\u5c31\u5920\u4e86\u3002\\n\\n\u9019\u6a23\u601d\u8003\u4e0b\u4f86\uff0c\u672a\u4f86\u5728\u6eff\u8db3\u5225\u4eba\u8207\u6eff\u8db3\u81ea\u5df1\u4e4b\u9593\u505a\u9078\u64c7\uff0c\u883b\u5bb9\u6613\u7684\u5427\uff1f\\n\\n\u6211\u5c0d\u81ea\u5df1\u7684\u9078\u64c7\u9084\u662f\u633a\u6eff\u610f\u7684\u3002"}]}}')}}]);